    switch (opcode) {
      case 0:
        if (destroyed) return;
        onRemoved?.call();
      case 1:
        final _name = r.uint32();
        if (destroyed) return;
        onWlSeat?.call(_name);
      case 2:
        final _window = connection.lookup(r.uint32()) as RiverWindowV1?;
        if (destroyed) return;
        if (_window == null) return;
        onPointerEnter?.call(_window!);
      case 3:
        if (destroyed) return;
        onPointerLeave?.call();
      case 4:
        final _window = connection.lookup(r.uint32()) as RiverWindowV1?;
        if (destroyed) return;
        if (_window == null) return;
        onWindowInteraction?.call(_window!);
      case 5:
        final _shellSurface = connection.lookup(r.uint32()) as RiverShellSurfaceV1?;
        if (destroyed) return;
        if (_shellSurface == null) return;
        onShellSurfaceInteraction?.call(_shellSurface!);
      case 6:
        final _dx = r.int32();
        final _dy = r.int32();
        if (destroyed) return;
        onOpDelta?.call(_dx, _dy);
      case 7:
        if (destroyed) return;
        onOpRelease?.call();
      case 8:
        final _x = r.int32();
        final _y = r.int32();
        if (destroyed) return;
        onPointerPosition?.call(_x, _y);
      case 9:
        final _touchPoint = r.int32();
        final _dx = r.int32();
        final _dy = r.int32();
        if (destroyed) return;
        onOpDeltaTouch?.call(_touchPoint, _dx, _dy);
      case 10:
        final _touchPoint = r.int32();
        if (destroyed) return;
        onOpReleaseTouch?.call(_touchPoint);
      case 11:
        final _touchPoint = r.int32();
        if (destroyed) return;
        onOpCancelTouch?.call(_touchPoint);
    }
  }
}

/// `river_seat_v1.modifiers` (bitfield)
abstract final class RiverSeatV1Modifiers {
  static const int none = 0;
  static const int shift = 1;
  static const int ctrl = 4;
  /// commonly called alt
  static const int mod1 = 8;
  static const int mod3 = 32;
  /// commonly called super or logo
  static const int mod4 = 64;
  static const int mod5 = 128;
}

/// configure a pointer binding, receive trigger events
class RiverPointerBindingV1 extends Proxy {
  RiverPointerBindingV1(super.connection, super.id, super.version);

  static const WaylandInterface<RiverPointerBindingV1> interface =
      WaylandInterface('river_pointer_binding_v1', 6, RiverPointerBindingV1.new);

  @override
  String get interfaceName => 'river_pointer_binding_v1';

  /// destroy the pointer binding object
  void destroy() {
    final WireWriter w = WireWriter(id, 0);
    send(w);
    markDestroyed();
  }

  /// enable the pointer binding
  void enable() {
    final WireWriter w = WireWriter(id, 1);
    send(w);
  }

  /// disable the pointer binding
  void disable() {
    final WireWriter w = WireWriter(id, 2);
    send(w);
  }

  /// the bound pointer button has been pressed
  void Function()? onPressed;

  /// the bound pointer button has been released
  void Function()? onReleased;

  @override
  void dispatchEvent(int opcode, WireReader r) {
    switch (opcode) {
      case 0:
        if (destroyed) return;
        onPressed?.call();
      case 1:
        if (destroyed) return;
        onReleased?.call();
    }
  }
}

